(function(){'use strict';var autoRefreshTimer=null;var currentPage=1;var pageSize=50;window.loadAuditLogs=loadAuditLogs;window.currentPage=1;window.pageSize=pageSize;function switchTab(name){document.querySelectorAll('.logs-page .tabs .tab-btn').forEach(function(el){el.classList.toggle('active',el.dataset.tab===name);el.setAttribute('aria-selected',el.dataset.tab===name?'true':'false');});document.querySelectorAll('.logs-page .tab-content').forEach(function(el){el.classList.toggle('active',el.id==='tab-'+name);});if(name==='audit-logs'){loadActionTypes();loadAuditLogs(1);stopAutoRefresh();}else{toggleAutoRefresh();}}
function fetchLogLines(level,tail){return fetch('/api/logs?level='+encodeURIComponent(level)+'&tail='+tail,{credentials:'same-origin'}).then(function(r){if(r.status===400||r.status===422){return fetch('/api/logs?tail='+tail,{credentials:'same-origin'}).then(function(r2){return r2.json();}).then(function(data){var lines=data.logs||[];if(level==='ALL')return lines;return lines.filter(function(line){return line.toUpperCase().indexOf(level.toUpperCase())!==-1;});});}
return r.json().then(function(data){return data.logs||[];});});}
var LOG_LEVEL_RE=/^\[[^\]]*\]\s+\[(\w+)\]/;function logLineClass(line){var m=LOG_LEVEL_RE.exec(line||'');if(!m)return'log-line';var level=m[1].toUpperCase();if(level==='ERROR'||level==='CRITICAL')return'log-line log-error';if(level==='WARNING'||level==='WARN')return'log-line log-warn';if(level==='DEBUG')return'log-line log-debug';return'log-line';}
function refreshLogs(){var level=document.getElementById('log-level').value;var tail=document.getElementById('log-tail').value;fetchLogLines(level,tail).then(function(logLines){var html=logLines.map(function(line){return'<div class="'+logLineClass(line)+'">'+LSM.escapeHtml(line)+'</div>';}).join('');document.getElementById('logs-content').innerHTML=html;var countEl=document.getElementById('log-count');if(countEl)countEl.textContent='共 '+logLines.length+' 行';}).catch(function(e){document.getElementById('logs-content').innerHTML='<div class="alert alert-error">加载失败: '+
LSM.escapeHtml((e&&e.message)?e.message:'网络错误')+'</div>';});}
function isAppTabActive(){return!document.getElementById('tab-audit-logs').classList.contains('active');}
function stopAutoRefresh(){if(autoRefreshTimer){clearInterval(autoRefreshTimer);autoRefreshTimer=null;}}
function toggleAutoRefresh(){stopAutoRefresh();if(document.getElementById('auto-refresh').checked&&isAppTabActive()&&!document.hidden){autoRefreshTimer=setInterval(refreshLogs,5000);}}
function downloadLogs(){fetch('/api/logs?level=ALL&tail=99999',{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(logData){var blob=new Blob([(logData.logs||[]).join('\n')],{type:'text/plain;charset=utf-8'});var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='app.log';document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(a.href);}).catch(function(e){LSM.showToast((e&&e.message)?e.message:'下载失败','error');});}
function loadActionTypes(){fetch('/api/audit/actions',{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(actions){var sel=document.getElementById('audit-action-filter');if(!sel)return;while(sel.options.length>1)sel.remove(1);(actions||[]).forEach(function(a){var opt=document.createElement('option');opt.value=a;opt.textContent=actionLabels[a]||a;sel.appendChild(opt);});}).catch(function(){});}
function loadAuditLogs(page){page=page||1;currentPage=page;window.currentPage=page;var action=document.getElementById('audit-action-filter').value;var url='/api/audit?page='+page+'&size='+pageSize;if(action)url+='&action='+encodeURIComponent(action);fetch(url,{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(data){renderAuditLogs(data);}).catch(function(e){document.getElementById('audit-list').innerHTML='<div class="alert alert-error">加载失败: '+
LSM.escapeHtml((e&&e.message)?e.message:'网络错误')+'</div>';});}
document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.logs-page .tabs .tab-btn').forEach(function(btn){btn.addEventListener('click',function(){var tabName=btn.dataset.tab;if(tabName)switchTab(tabName);});});var levelSel=document.getElementById('log-level');if(levelSel)levelSel.addEventListener('change',refreshLogs);var tailInput=document.getElementById('log-tail');if(tailInput)tailInput.addEventListener('change',refreshLogs);var refreshBtn=document.getElementById('btn-refresh-logs');if(refreshBtn)refreshBtn.addEventListener('click',refreshLogs);var downloadBtn=document.getElementById('btn-download-logs');if(downloadBtn)downloadBtn.addEventListener('click',downloadLogs);var auditFilter=document.getElementById('audit-action-filter');if(auditFilter)auditFilter.addEventListener('change',function(){loadAuditLogs(1);});var auditRefreshBtn=document.getElementById('btn-refresh-audit');if(auditRefreshBtn)auditRefreshBtn.addEventListener('click',function(){loadAuditLogs(currentPage);});toggleAutoRefresh();refreshLogs();document.addEventListener('visibilitychange',function(){if(document.hidden){stopAutoRefresh();}else if(isAppTabActive()){toggleAutoRefresh();refreshLogs();}});});})();